.chat-context-source-row > :nth-child(5) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-chat-secondary);
}

.chat-context-source-row > :nth-child(5) svg {
  width: 14px;
  height: 14px;
}

.chat-context-details :is(code, .font-mono) {
  font-size: 12px;
  line-height: 16px;
  overflow-wrap: anywhere;
}

.chat-context-details button:focus-visible {
  outline: 1.5px solid color-mix(in srgb, var(--color-chat-foreground) 28%, transparent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .chat-context-token-tag .ant-progress-circle-path {
    transition: none !important;
  }
}
